document.querySelector('.menu-toggle')?.addEventListener('click',e=>{const m=document.querySelector('.nav-links');const open=m.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',open)});if('IntersectionObserver' in window){const o=new IntersectionObserver(es=>es.forEach(x=>{if(x.isIntersecting){x.target.classList.add('is-visible');o.unobserve(x.target)}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(x=>o.observe(x))}else document.querySelectorAll('.reveal').forEach(x=>x.classList.add('is-visible'));const f=document.querySelector('#wa-form');f?.addEventListener('submit',e=>{e.preventDefault();if(!f.reportValidity())return;const d=new FormData(f);const msg=`Hi Nitesh, I found your portfolio and would like to discuss a project.\n\nName: ${d.get('name')}\nContact: ${d.get('contact')}\nService: ${d.get('service')}\nWebsite: ${d.get('website')||'Not provided'}\nProject details: ${d.get('details')}`;const link='https://wa.me/917974823298?text='+encodeURIComponent(msg);document.querySelector('#wa-status').textContent='Opening WhatsApp with your message. Please press Send there to deliver it.';window.open(link,'_blank','noopener,noreferrer')});